) as k(code, kit)
join public.card_definitions d on d.code = k.code
on conflict (definition_id) do nothing;

do $$
begin
  if (select count(*) from public.card_definitions d join public.combat_kits k on k.definition_id = d.id
      where d.code in ('P328', 'P329', 'P330', 'P331', 'P332', 'P333', 'P334', 'P335', 'P336', 'P337', 'P338', 'P339', 'P340', 'P341', 'P342', 'P343', 'P344', 'P345', 'P346', 'P347', 'P348', 'P349', 'P350', 'P351')) <> 24 then
    raise exception 'a character of the fourteenth batch has no kit';
  end if;
end $$;
